import SwiftUIimport FirebaseAuthimport FirebaseFirestore // Required to talk to the databasestruct SignupView: View {    @State private var name = "" // Added Name field    @State private var email = ""    @State private var password = ""    @State private var confirmPassword = ""    @State private var errorMessage = ""            var body: some View {        ZStack {            Color.orange.ignoresSafeArea()                        VStack(spacing: 20) {                Text("Create Account")                    .font(.system(size: 40, weight: .bold))                    .foregroundColor(.white)                    .padding(.bottom, 30)                                // New Name Input                TextField("Full Name", text: $name)                    .textFieldStyle(.roundedBorder)                    .padding(.horizontal, 30)                                TextField("University Email (.edu)", text: $email)                    .textFieldStyle(.roundedBorder)                    .autocapitalization(.none)                    .keyboardType(.emailAddress)                    .padding(.horizontal, 30)                                SecureField("Password", text: $password)                    .textFieldStyle(.roundedBorder)                    .padding(.horizontal, 30)                                SecureField("Confirm Password", text: $confirmPassword)                    .textFieldStyle(.roundedBorder)                    .padding(.horizontal, 30)                                if !errorMessage.isEmpty {                    Text(errorMessage)                        .foregroundColor(.white)                        .font(.subheadline)                        .bold()                }                                Button(action: registerUser) {                    Text("Sign Up")                        .font(.headline)                        .foregroundColor(.orange)                        .frame(maxWidth: .infinity)                        .padding()                        .background(Color.white)                        .cornerRadius(12)                }                .padding(.horizontal, 30)                .padding(.top, 10)            }        }        .tint(.white)    }        func registerUser() {            errorMessage = ""                        guard password == confirmPassword else {                errorMessage = "Passwords do not match."                return            }            guard !name.isEmpty else {                errorMessage = "Please enter your name."                return            }                        Auth.auth().createUser(withEmail: email, password: password) { result, error in                if let error = error {                    errorMessage = error.localizedDescription                    return                }                                // 1. Grab the user object                guard let user = result?.user else { return }                                // sned verification email                user.sendEmailVerification { error in                    if let error = error {                        errorMessage = "Failed to send verification email."                        return                    }                                        // build firestore profile                    let db = Firestore.firestore()                    let userData: [String: Any] = [                        "uid": user.uid,                        "email": email,                        "displayName": name,                        "university": "Washington University in St. Louis",                        "rating": 5.0,                        "completedOrders": 0                    ]                                        db.collection("users").document(user.uid).setData(userData) { error in                        if error != nil {                            errorMessage = "Account created, but database failed."                        } else {                            errorMessage = "Success! A verification link has been sent to \(email). Please click it to activate your account."                                                    }                    }                }            }        }}#Preview {    SignupView()}